SELECT COUNT(DISTINCT UserId) AS num_users
FROM badges
WHERE Name = 'Announcer';

SELECT
  (SELECT COUNT(Id) FROM votes WHERE strftime('%Y', CreationDate) = '2010') * 1.0 /
  (SELECT COUNT(Id) FROM votes WHERE strftime('%Y', CreationDate) = '2011') AS ratio_2010_to_2011;

SELECT DisplayName, Age
FROM users
WHERE Views = (SELECT MAX(Views) FROM users);

SELECT LastEditDate, LastEditorUserId
FROM posts
WHERE Title = 'Detecting a given face in a database of facial images';

SELECT OwnerUserId
FROM posts
WHERE FavoriteCount = (SELECT MAX(FavoriteCount) FROM posts);

SELECT Id
FROM users
WHERE Age = (SELECT MIN(Age) FROM users);

SELECT DisplayName
FROM users
WHERE Reputation = (SELECT MAX(Reputation) FROM users);

SELECT COUNT(*) 
FROM posts 
WHERE ViewCount > 35000 AND CommentCount = 0;

SELECT Reputation, Views
FROM users
WHERE DisplayName = 'Jarrod Dixon';

SELECT (COUNT(CASE WHEN Currency = 'Euro' THEN 1 END) * 100.0 / COUNT(*)) AS PercentageKAMEuro
FROM customers
WHERE Segment = 'KAM';

SELECT player_api_id
FROM Player_Attributes
WHERE overall_rating = (SELECT MAX(overall_rating) FROM Player_Attributes);

SELECT DISTINCT team_fifa_api_id
FROM Team_Attributes
WHERE buildUpPlaySpeed > 50 AND buildUpPlaySpeed < 60;

SELECT player_name
FROM Player
WHERE height = (SELECT MAX(height) FROM Player);

SELECT SUM(CASE WHEN A3 = 'north Bohemia' THEN A16 ELSE 0 END)
     - SUM(CASE WHEN A3 = 'east Bohemia' THEN A16 ELSE 0 END) AS crime_difference_1996
FROM district;

SELECT first_name, last_name, email
FROM member
WHERE position = 'Secretary';

SELECT SUM(type = 'Community Service') * 100.0 / COUNT(event_id) AS percentage
FROM event
WHERE event_date BETWEEN '2019-01-01' AND '2019-12-31';

SELECT full_name
FROM superhero
WHERE weight_kg = 0 OR weight_kg IS NULL;

SELECT full_name
FROM superhero
WHERE superhero_name = 'Alien';

SELECT CAST(SUM(CASE WHEN Admission = '+' THEN 1 ELSE 0 END) AS REAL) / SUM(CASE WHEN Admission = '-' THEN 1 ELSE 0 END) AS deviation_percentage
FROM Patient
WHERE SEX = 'M';

SELECT CAST(SUM(CASE WHEN Admission = '+' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(*) AS percentage_inpatient
FROM Patient
WHERE year(Birthday) BETWEEN '1930-01-01' AND '1940-12-31';

SELECT DISTINCT element
FROM atom
WHERE molecule_id = 'TR004';

SELECT label
FROM molecule
WHERE molecule_id IN ('TR000', 'TR001', 'TR002');

SELECT SUM(CASE WHEN bond_type = ' = ' THEN 1 ELSE 0 END) * 100.0 / COUNT(bond_id) AS percent
FROM bond
WHERE molecule_id = 'TR047';

SELECT COUNT(*)
FROM molecule
WHERE molecule_id NOT IN (
    SELECT molecule_id FROM atom WHERE element = 's'
)
AND molecule_id NOT IN (
    SELECT molecule_id FROM bond WHERE bond_type = ' = '
);
